vec4 colLerp(vec4 a, vec4 b, float t){
    return a + (b-a)*t;
}
float map(float val, float minIn, float maxIn, float minOut, float maxOut){
    return (val - minIn)/(maxIn-minIn) * (maxOut-minOut) + minOut;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;
    //true vision
    vec4 sight = texture(iChannel0,uv);
    //fake vision
    vec4 weird = texture(iChannel1,uv);

    //lerp between true vision or fake vision
    vec2 pos = uv - vec2(0.5);
    pos.x *= iResolution.x/iResolution.y;
    pos.xy *= vec2(1.0,1.25);
    float t = length(pos);//distance from center of vision
    t = clamp(map(t,0.0,0.5,-3.0,0.0),0.0,1.0);


    // Output to screen
    fragColor = colLerp(sight,weird,t);
}

const vec2 hexSide = vec2(1.7320508, 1);

float hash13(vec3 p3)
{
	p3  = fract(p3 * .1031);
    p3 += dot(p3, p3.zyx + 31.32);
    return fract((p3.x + p3.y) * p3.z);
}
vec3 hash33(vec3 p3)
{
	p3 = fract(p3 * vec3(.1031, .1030, .0973));
    p3 += dot(p3, p3.yxz+33.33);
    return fract((p3.xxy + p3.yxx)*p3.zyx);

}

vec3 hexUV(vec2 fragCoord){

    vec2 uv = (fragCoord - iResolution.xy * .5)/iResolution.y;

    uv *= 40.;

    //uv *= 1.0 - sqrt(length(uv))/8.5;

    // hexagon center points
    vec2 hc1 = floor(uv / hexSide) + .5;
    vec2 hc2 = floor((uv - vec2(sqrt(3.)/2., .5)) / hexSide) + .5;

    // rectangular grids
    vec2 rg1 = vec2(uv - hc1 * hexSide);
    vec2 rg2 = vec2(uv - (hc2 + .5) * hexSide);

    vec2 hexGrid = length(rg1) < length(rg2) ? rg1 : rg2;

    // this is the part where you drop your jaw in amazement
    return vec3(hexGrid, 0);

}
